#include <stdio.h>
#include <string.h>
int main(void){
  long long diffbits=0, diffstr=0, n=0;
  for (long long i=-5000000; i<=5000000; i++){
    int cur=(int)i; n++;
    float a=((float)cur/200.0f)*100.0f;
    float b=((float)cur*100.0f)/200.0f;
    if (a!=b){ diffbits++;
      char sa[64],sb[64];
      snprintf(sa,sizeof sa,"%.1f",(double)a);
      snprintf(sb,sizeof sb,"%.1f",(double)b);
      if(strcmp(sa,sb)) diffstr++;
    }
  }
  printf("range +/-5e6: n=%lld bit-differs=%lld printed-differs=%lld\n",n,diffbits,diffstr);
  /* smallest magnitude printed-difference */
  for (long long i=0;i<=100000000;i++){
    int cur=(int)i;
    float a=((float)cur/200.0f)*100.0f, b=((float)cur*100.0f)/200.0f;
    if(a==b) continue;
    char sa[64],sb[64];
    snprintf(sa,sizeof sa,"%.1f",(double)a); snprintf(sb,sizeof sb,"%.1f",(double)b);
    if(strcmp(sa,sb)==0) continue;
    printf("smallest positive printed-difference: cur=%d div=%s mul=%s\n",cur,sa,sb); break;
  }
  return 0;
}
EOF
